{
  "claims": [
    {
      "claim": "基站需靠墙放置",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]明确要求“靠墙放置基站”。"
    },
    {
      "claim": "基站前方须保留1.5米以上、两侧各0.5米以上的无障碍空间",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]提示“确保基站前方有1.5米以上，两侧有0.5米以上空间”。"
    },
    {
      "claim": "空间不足可能阻碍主机识别或进入基站",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段未说明空间不足与主机识别或进入基站之间的关系。"
    },
    {
      "claim": "空间不足会影响智能回充功能正常触发",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段未将空间要求与智能回充触发关联。"
    },
    {
      "claim": "若电源线未收好，可能被主机拖拽导致基站位移或断电",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文为“注意收好电源线，否则可能被主机拖拽，引起基站位移或断电”。"
    },
    {
      "claim": "基站位移或断电会中断回充过程",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段未提及回充过程会因此中断。"
    },
    {
      "claim": "初次使用时需手动将主机靠上基站，并确保充电极片与充电弹片对准",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]写有“初次使用时，请将主机手动靠上基站，充电极片对准充电弹片”。"
    },
    {
      "claim": "日常使用才可依赖智能回充",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]说明日常使用时可直接短按启动智能回充，支持该操作关系。"
    },
    {
      "claim": "其余关于基站摆放角度、地面平整度、环境光照、电磁干扰等对回充的影响，资料片段中未提及",
      "verdict": "supported",
      "evidence_index": null,
      "reason": "检索片段中确实没有涉及这些因素。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "需确认清水箱已安装到位",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "检索片段中没有“确认清水箱安装到位”的表述，仅提到补充清水箱水量。"
    },
    {
      "claim": "加入市政自来水至最高水位线以下",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段[2]明确说明“加入市政自来水至最高水位线以下”。"
    },
    {
      "claim": "若提示“清水箱已空”，需及时添加清水",
      "verdict": "supported",
      "evidence_index": 5,
      "reason": "片段[5]故障排除中有“清水箱已空，请及时添加清水”。"
    },
    {
      "claim": "需定期清理清水箱中的过滤管",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]提示“定期清理清水箱过滤管”。"
    },
    {
      "claim": "清理过滤管的具体步骤：取出清水箱，拔出过滤管，抠开滤盖，清洗滤盖和海绵网，清理完毕后重新装回过滤管",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]详细描述了该操作步骤。"
    },
    {
      "claim": "提示“定期清理清水箱过滤管，避免污垢堵塞过滤管”",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]原文有该提示。"
    },
    {
      "claim": "需确认污水箱已安装到位",
      "verdict": "supported",
      "evidence_index": 5,
      "reason": "片段[5]故障排除中包含“确认污水箱安装到位”或“检查污水箱是否安装到位”。"
    },
    {
      "claim": "否则可能触发“清洗槽已满”或“请检查并清理清洗槽，并确认污水箱安装到位”等故障提示",
      "verdict": "supported",
      "evidence_index": 5,
      "reason": "片段[5]列有这两个故障提示，且均关联污水箱安装检查。"
    },
    {
      "claim": "资料片段未涉及水路堵塞、水泵故障、基站清洗功能异常、APP设置或固件问题等内容",
      "verdict": "supported",
      "evidence_index": null,
      "reason": "通览全部检索片段，均未出现这些主题。"
    }
  ]
}

{
  "claims": [
    {
      "claim": "确认手机连接的是 2.4GHz Wi-Fi",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤1要求确认手机连接2.4GHz Wi-Fi"
    },
    {
      "claim": "若为双频合一路由器，建议临时将 2.4G 和 5G 的 Wi-Fi 名称分开",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤1有相同建议"
    },
    {
      "claim": "长按基站上的召回键与清洗键 3 秒，待机器语音提示进入配网模式",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤2描述相同操作"
    },
    {
      "claim": "在 App 中删除旧设备记录后，重新扫描水箱盖内侧二维码进行绑定",
      "verdict": "supported",
      "evidence_index": 2,
      "reason": "片段2步骤3描述相同操作"
    },
    {
      "claim": "本机仅支持 2.4GHz Wi-Fi",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "片段只说支持2.4GHz，并未排除5GHz，'仅'字无依据"
    },
    {
      "claim": "配网失败时请优先使用 2.4GHz 网络",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1有相同建议"
    },
    {
      "claim": "将机器移至路由器附近",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1有相同建议"
    },
    {
      "claim": "路由器建议关闭 AP 隔离与访客网络限制",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1有相同建议"
    },
    {
      "claim": "Wi-Fi 名称避免使用特殊符号",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1有相同建议"
    },
    {
      "claim": "若曾绑定过该设备，App 中删除旧设备记录后再重新扫码可解决大部分绑定异常",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段1提到删除旧记录后重新扫码可解决大部分绑定异常"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于联系售后的兜底话术，非事实性内容"
    }
  ]
}

{
  "claims": [
    {
      "claim": "针对RC-M500型号污水箱一直报警的问题，应按以下顺序自助排查",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]明确写明适用问题为RC-M500污水箱报警排查，并给出按顺序执行的步骤"
    },
    {
      "claim": "步骤1：取出污水箱倒掉污水并用清水冲洗",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1原文即此操作"
    },
    {
      "claim": "污水箱满或浮子卡住都会触发报警",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1中明确说明"
    },
    {
      "claim": "步骤2：冲洗污水箱内的白色浮子并确认其上下浮动自如",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2原文"
    },
    {
      "claim": "步骤3：擦干污水箱底部与基站接口后装回，确认到位后报警应消除",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3原文"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在，请停止自助排查并联系官方售后",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]最后一句"
    },
    {
      "claim": "该排查流程仅适用于RC-M500型号",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]开头指明适用问题为RC-M500"
    },
    {
      "claim": "其他型号未在资料中覆盖",
      "verdict": "unsupported",
      "evidence_index": null,
      "reason": "检索片段未提及任何其他型号的信息，无法支持该论断"
    }
  ]
}

{
  "claims": [
    {
      "claim": "步骤1：将机器放上基站充电 30 分钟，因深度亏电后需充电半小时才能开机",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤1明确说明深度亏电后需充电半小时才能开机，请先把机器放上基站。"
    },
    {
      "claim": "步骤2：确认机身侧面总开关处于 ON 位置",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤2明确要求确认机身侧面总开关在 ON 位置。"
    },
    {
      "claim": "步骤3：检查机器充电极片与基站弹片是否贴合",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3明确要求确认机器充电极片与基站弹片贴合。"
    },
    {
      "claim": "步骤3：指示灯亮起表示充电正常",
      "verdict": "supported",
      "evidence_index": 1,
      "reason": "片段[1]步骤3写明指示灯亮起表示充电正常。"
    },
    {
      "claim": "以上步骤全部执行后问题仍存在，请停止自助排查并联系官方售后",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于联系售后的兜底话术，非事实性内容。"
    },
    {
      "claim": "其余资料片段涉及错误码（如 E03–E11）、App 配网等问题，与“开不了机没有反应”无直接关联，不适用",
      "verdict": "uncheckable",
      "evidence_index": null,
      "reason": "属于对引用资料适用性的元评论和引用格式标注，非产品事实论断。"
    }
  ]
}
